import Product from '../Product'

const ProductsList = ({ pratos, title, background, isHome, onProductClick }) => {
  return (
    <div style={{ background: background }}>
      <h2>{title}</h2>
      <div>
        {pratos.map((prato) => (
          <Product
            key={prato.id}
            {...prato}
            $isHome={isHome}
            onClick={() => onProductClick(prato)} // Passa o produto clicado para a função
          />
        ))}
      </div>
    </div>
  )
}

export default ProductsList
